const MAX_ITEMS = 30;
const items = $input.all().map((it) => it.json).slice(0, MAX_ITEMS);
return [{ json: { count: items.length, items } }];

const WINDOW_DAYS = 3;
const cutoff = Date.now() - WINDOW_DAYS * 864e5;

const clean = (s) =>
  String(s ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

// Feeds scatter the date across different fields — check the usual suspects.
const getWhen = (j) => {
  const raw = j.isoDate || j.pubDate || j.published || j.date || j.updated || j.created;
  if (!raw) return null;                 // no date found → keep it, don't guess
  const t = new Date(raw).getTime();
  return Number.isFinite(t) ? t : null;
};

const seen = new Set();
const out = [];

for (const it of $input.all()) {
  const j = it.json;

  const when = getWhen(j);
  if (when !== null && when < cutoff) continue;   // only skip if we KNOW it's old

  const key = clean(j.link || j.guid || j.title).split('?')[0];
  if (!key || seen.has(key)) continue;            // duplicate → skip
  seen.add(key);

  out.push({
    json: {
      title: clean(j.title),
      link: j.link || '',
      date: j.isoDate || j.pubDate || j.published || null,
      snippet: clean(j.contentSnippet || j.content || j.description).slice(0, 400),
    },
  });
}

out.sort((a, b) => new Date(b.json.date || 0) - new Date(a.json.date || 0));  // newest first
return out;

