=You are the editor of "Insecure Mail", a weekly cybersecurity newsletter. Edition: {{ $('Editions').first().json.key }}.
From the RSS items below, choose the most important, credible stories for a technical-but-busy audience (engineers, sysadmins, security folks). Prefer actively exploited CVEs, major breaches, widely-used software, and practical guidance. Ignore vendor fluff, listicles, and duplicates.
Write the issue as clean, email-safe HTML (no <html>/<head>; only h2,h3,p,ul,li,a,strong,code,hr). ~5 minute read. One-line intro, then each story with a bold headline, a 2-4 sentence plain-English summary, why it matters, and a source link. End with a short 'CVEs worth your time' list if relevant.Return STRICT JSON, no markdown fence: {"title":"short subject line, no date","summary":"1-2 sentence teaser","body_html":"full issue HTML"}

RSS_ITEMS:
{{ JSON.stringify($json.items) }}

parameters.jsCode:
const raw = $json.content.parts[0].text;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // fallback in case the model wraps it in a code fence despite instructions
  const cleaned = raw.replace(/^```json\s*|```\s*$/g, '').trim();
  parsed = JSON.parse(cleaned);
}

const edition = $('Editions').first().json;

const html = `
<!DOCTYPE html>
<html>
<body style="margin:0;padding:0;background:#0b0f14;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#0b0f14;padding:32px 0;">
    <tr>
      <td align="center">
        <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;">
          <tr>
            <td style="background:#0b0f14;padding:20px 32px;">
              <span style="color:#22d3ee;font-family:monospace;font-size:12px;letter-spacing:.05em;">
                INSECURE MAIL · ${edition.edition || ''}
              </span>
            </td>
          </tr>
          <tr>
            <td style="padding:32px;color:#111827;font-size:15px;line-height:1.6;">
              ${parsed.body_html}
            </td>
          </tr>
          <tr>
            <td style="padding:20px 32px;background:#f3f4f6;color:#6b7280;font-size:12px;">
              You are receiving this because you subscribed to Insecure Mail.
              <a href="{{ unsubscribe_link }}" style="color:#6b7280;">Unsubscribe</a>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>
`;

return [{
  json: {
    subject: parsed.title,
    teaser: parsed.summary,
    html
  }
}];
